c(2) = exp(x(4)) + 2*exp(x(5)) + exp(x(6)) + exp(x(7)) - 1;
c(3) = exp(x(10)) + exp(x(3)) + exp(x(7)) + exp(x(8)) + 2*exp(x(9)) - 1;
end

function J = HS111_J(x)
